package com.lmspilot.notification.domain; import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="notification_templates") public class NotificationTemplateEntity{@Id public UUID id=UUID.randomUUID();@Column(nullable=false,unique=true,length=80)public String code="";@Column(nullable=false,length=120)public String eventType="";@Column(nullable=false,length=240)public String titleTemplate="";@Column(nullable=false,columnDefinition="text")public String bodyTemplate="";@Column(nullable=false)public boolean active=true;@Column(nullable=false)public Instant createdAt=Instant.now();@Column(nullable=false)public Instant updatedAt=Instant.now();@Version public long version;public NotificationTemplateEntity(){}}
